INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 16, 27, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", "獣人族", 0, 8, 2, 155, "トゥインクルウィッシュ", "東山奈央", "ヒヨリ", "人助け、応援", 100101, 44);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 5, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", "ヒューマン", 0, 4, 2, 158, "トゥインクルウィッシュ", "種田梨沙", "ユイ", "料理、人間観察", 100201, 47);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 18, 12, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", "魔族", 0, 1, 2, 163, "トゥインクルウィッシュ", "早見沙織", "レイ", "読書、乗馬、お茶", 100301, 46);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 9, 10, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "探検好きのイタズラっ子", "ヒューマン", 0, 8, 5, 128, "リトルリリカル", "諸星すみれ", "ミソギ", "いたずら、探検", 100401, 27);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 12, 25, "？？？", "ヒーローに憧れる騎士見習いの少女", "獣人族", 0, 11, 8, 146, "王宮騎士団（NIGHTMARE）", "下田麻美", "マツリ", "ヒーローごっこ", 100501, 40);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 13, 22, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "甘え上手なみんなの人気者", "魔族", 0, 11, 7, 150, "悪魔偽王国軍（ディアボロス）", "浅倉杏美", "アカリ", "サックス", 100601, 42);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 14, 23, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリン大好きゴースト娘", "魔族", 0, 1, 7, 130, "悪魔偽王国軍（ディアボロス）", "雨宮天", "ミヤコ", "プリンを食べること", 100701, 32);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 14, 10, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ボクは誰よりも美しい", "エルフ", 0, 10, 15, 150, "ヴァイスフリューゲル　ランドソル支部", "大空直美", "ユキ", "鏡で自分を見ること", 100801, 40);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 5, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "前世を信じる中二病患者、「疾風の冥姫」", "魔族", 0, 7, 13, 159, "トワイライトキャラバン", "髙野麻美", "アンナ", "小説執筆", 100901, 45);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 22, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "マホマホ王国のプリンセス", "獣人族", 0, 9, 10, 155, "自警団（カォン）", "内田真礼", "マホ", "空想、ぬいぐるみ集め", 101001, 42);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 15, 25, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "人懐っこくてマシンガントークな妹系少女", "ヒューマン", 0, 8, 3, 156, "ラビリンス", "阿澄佳奈", "リノ", "お裁縫", 101101, 44);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 24, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "みんなのために超能力を使う眠り姫", "エルフ", 0, 12, 6, 156, "フォレスティエ", "大橋彩香", "ハツネ", "妹と遊ぶこと、二度寝、昼寝、早寝", 101201, 46);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 18, 21, "", "オタク全開な魔法少女", "魔族", 0, 8, 13, 166, "トワイライトキャラバン", "佳村はるか", "ナナカ", "読書、魔法", 101301, 55);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 15, 3, "test", "頭脳明晰な美少女名探偵", "獣人族", 0, 11, 10, 152, "自警団（カォン）", "水瀬いのり", "カスミ", "読書、推理", 101401, 41);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 21, 5, "test", "母性溢れる優しいみんなの「ミサト先生」", "エルフ", 0, 9, 6, 165, "フォレスティエ", "國府田マリ子", "ミサト", "絵本作り", 101501, 54);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 10, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "天真爛漫で人気者のカリスマモデル", "魔族", 0, 4, 14, 167, "ルーセント学院", "上坂すみれ", "スズナ", "ファッション", 101601, 48);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 7, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "いつでも「なんくるないさ～」な天然娘", "獣人族", 0, 7, 10, 158, "自警団（カォン）", "高森奈津美", "カオリ", "踊り、空手", 101701, 53);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 23, 14, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "多くの男性を魅了する無垢な女教師", "魔族", 0, 8, 14, 162, "ルーセント学院", "伊藤静", "イオ", "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 101801, 52);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 10, 3, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "お歌もにんじんも、ウサギさんも大好き♪", "獣人族", 0, 4, 5, 117, "リトルリリカル", "日高里菜", "ミミ", "かわいいもの集め", 102001, 21);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 12, 9, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "泣き虫で臆病な守ってあげたい女の子", "ヒューマン", 0, 6, 9, 150, "サレンディア救護院", "植田佳奈", "クルミ", "観劇、おままごと", 102101, 40);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 13, 22, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "人見知りであまのじゃくな女の子", "魔族", 0, 11, 7, 150, "悪魔偽王国軍（ディアボロス）", "原紗友里", "ヨリ", "ゲーム全般", 102201, 40);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 14, 10, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "ぷうきちといつも一緒！", "ヒューマン", 0, 5, 9, 148, "サレンディア救護院", "芹澤優", "アヤネ", "屋内でできる遊び", 102301, 38);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 15, 12, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "お嬢さまのためにがんばるドジっ娘メイド", "ヒューマン", 0, 12, 9, 154, "サレンディア救護院", "悠木碧", "スズメ", "ご奉仕", 102501, 43);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 17, 1, "test", "遊びと睡眠が何より大事なぐうたら娘", "獣人族", 0, 1, 11, 144, "牧場（エリザベスパーク）", "小岩井ことり", "リン", "あんパン", 102601, 42);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 16, 30, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "運命の相手に一途すぎる乙女", "魔族", 0, 7, 13, 154, "トワイライトキャラバン", "橋本ちなみ", "エリコ", "実験、裁縫、料理", 102701, 43);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 4, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "救護院を経営する優しい庶民派お嬢様", "エルフ", 0, 10, 9, 156, "サレンディア救護院", "堀江由衣", "サレン", "経営、お茶会", 102801, 43);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 17, 24, "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", "歌って踊れる大人気アイドル", "ヒューマン", 0, 1, 4, 157, "カルミナ", "日笠陽子", "ノゾミ", "舞台鑑賞、ダンス", 102901, 40);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 31, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "トーゴクの神秘、オシエテクダサイ！", "ヒューマン", 0, 8, 15, 163, "ヴァイスフリューゲル　ランドソル支部", "佐藤聡美", "ニノン", "忍法開発", 103001, 51);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 18, 22, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", "魔族", 0, 12, 7, 157, "悪魔偽王国軍（ディアボロス）", "大坪由佳", "シノブ", "占い", 103101, 42);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 18, 12, "この私とともにいる限り、\nお金に不自由はさせませんわ！", "一人前の商人を目指すパワフルお嬢様", "ヒューマン", 0, 3, 12, 157, "メルクリウス財団", "松嵜麗", "アキノ", "慈善事業", 103201, 45);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 20, 3, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "みんなを笑顔にするお笑い牧場主", "ヒューマン", 0, 3, 11, 142, "牧場（エリザベスパーク）", "新田恵海", "マヒル", "漫才", 103301, 35);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 22, 16, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "純情でほっとけない大人の女性", "エルフ", 0, 3, 12, 164, "メルクリウス財団", "今井麻美", "ユカリ", "ウインドーショッピング", 103401, 55);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 8, 2, "test", "礼儀正しくしっかり者のちびっ子優等生", "エルフ", 0, 2, 5, 118, "リトルリリカル", "小倉唯", "キョウカ", "お勉強", 103601, 21);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 13, 11, "test", "義理堅くてからかい好きな剣術少女", "ヒューマン", 0, 8, 8, 149, "王宮騎士団（NIGHTMARE）", "茅原実里", "トモ", "剣術、年長者をからかう", 103701, 43);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 14, 3, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "読書が趣味の病弱少女", "獣人族", 0, 11, 11, 153, "牧場（エリザベスパーク）", "小清水亜美", "シオリ", "読書、お散歩", 103801, 40);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 13, 6, "友達ができるその日まで…\nBB団で\nトレーニングですっ！", "「友達」に憧れる、エルフの森の女の子", "エルフ", 0, 6, 6, 158, "フォレスティエ", "花澤香菜", "アオイ", "友達作りのイメトレ", 104001, 44);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 3, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "人々を守るために歌う、唱喚士の少女", "ヒューマン", 0, 6, 4, 163, "カルミナ", "福原綾香", "チカ", "各種楽器", 104201, 46);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 9, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "男勝りで情に厚いワイルド娘", "獣人族", 0, 8, 10, 168, "自警団（カォン）", "小松未可子", "マコト", "お菓子作り", 104301, 54);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", "??", 5, "test", "かつては夜を支配した最強の吸血鬼", "魔族", 0, 5, 7, 172, "悪魔偽王国軍（ディアボロス）", "丹下桜", "イリヤ", "世界征服", 104401, 50);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 18, 19, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "妄想大好き！　ほんとは照れ屋な女の子", "ヒューマン", 0, 11, 15, 157, "ヴァイスフリューゲル　ランドソル支部", "長妻樹里", "クウカ", "小説を読むこと", 104501, 49);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 19, 1, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", "獣人族", 0, 3, 12, 158, "メルクリウス財団", "沼倉愛美", "タマキ", "猫とたわむれること", 104601, 48);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 25, 25, "？？？", "素顔を見せない冷静沈着な女性騎士", "ヒューマン", 0, 10, 8, 171, "王宮騎士団（NIGHTMARE）", "川澄綾子", "ジュン", "格闘技、湯浴み", 104701, 50);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 20, 11, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "仕事も私事も効率優先な傭兵少女", "ヒューマン", 0, 11, 12, 163, "メルクリウス財団", "田所あずさ", "ミフユ", "傭兵などのアルバイト", 104801, 49);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 18, 24, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "お姉ちゃんがお世話してあげるからねっ！", "ヒューマン", 0, 10, 3, 168, "ラビリンス", "生天目仁美", "シズル", "家事全般", 104901, 54);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 11, 3, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ちょっとおませな恋に恋する女の子", "魔族", 0, 1, 14, 120, "ルーセント学院", "久野美咲", "ミサキ", "ファッション誌鑑賞、コスメ集め", 105001, 22);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 27, 7, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "実験が趣味の危険な科学者", "ヒューマン", 0, 3, 13, 166, "トワイライトキャラバン", "三石琴乃", "ミツキ", "研究、実験", 105101, 53);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 14, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "乙女チックなもふもふアニマル", "獣人族", 0, 3, 11, 150, "牧場（エリザベスパーク）", "徳井青空", "リマ", "毛繕い、お喋り", 105201, 100);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 28, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "見た目も中身もお子ちゃまな異国の軍人", "ヒューマン", 0, 7, 15, 140, "ヴァイスフリューゲル　ランドソル支部", "辻あゆみ", "モニカ", "お菓子屋通い", 105301, 33);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 14, 7, "test", "ファッション大好きなキュートガール", "ヒューマン", 0, 9, 4, 153, "カルミナ", "木戸衣吹", "ツムギ", "裁縫", 105401, 45);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 7, "test", "どこまでも一途に慕う、純情乙女", "エルフ", 0, 4, 15, 155, "ヴァイスフリューゲル　ランドソル支部", "大関英里", "アユミ", "観察", 105501, 43);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 25, 11, "test", "人情味溢れる粋でいなせな「姉御」", "ヒューマン", 0, 7, 13, 167, "トワイライトキャラバン", "佐藤利奈", "ルカ", "釣り", 105601, 54);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 10, "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", "空への冒険を夢見る騎空士の少女", "ヒューマン", 0, 3, "", 156, "？？？", "金元寿子", "ジータ", "冒険、おしゃべり", 105701, 45);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 31, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "いつも元気な腹ペコ少女", "ヒューマン", 0, 3, 1, 156, "美食殿", "M・A・O", "ペコリーヌ", "食べ歩き、料理", 105801, 46);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 11, 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "主を慕う、小さなガイド役", "エルフ", 0, 5, 1, 140, "美食殿", "伊藤美来", "コッコロ", "瞑想、動植物の飼育", 105901, 35);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 14, 2, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "行き倒れの謎のネコミミ魔法使い", "獣人族", 0, 9, 1, 152, "美食殿", "立花理香", "キャル", "猫と遊ぶ", 106001, 39);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 11, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "さまよえる謎の少女", "ヒューマン", 0, 8, "", 148, "？？？", "潘めぐみ", "ムイミ", "冒険、思い出話", 106101, 40);
