INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 31, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "いつも元気な腹ペコ少女", "ヒューマン", 0, 3, 1, 156, "美食殿", "M・A・O", "ペコリーヌ（サマー）", "食べ歩き、料理", 107501, 46);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 11, 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "主を慕う、小さなガイド役", "エルフ", 0, 5, 1, 140, "美食殿", "伊藤美来", "コッコロ（サマー）", "瞑想、動植物の飼育", 107601, 35);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 15, 12, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "お嬢さまのためにがんばるドジっ娘メイド", "ヒューマン", 0, 12, 9, 154, "サレンディア救護院", "悠木碧", "スズメ（サマー）", "ご奉仕", 107701, 43);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 14, 2, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "行き倒れの謎のネコミミ魔法使い", "獣人族", 0, 9, 1, 152, "美食殿", "立花理香", "キャル（サマー）", "猫と遊ぶ", 107801, 39);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 19, 1, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", "獣人族", 0, 3, 12, 158, "メルクリウス財団", "沼倉愛美", "タマキ（サマー）", "猫とたわむれること", 107901, 48);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 20, 11, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "仕事も私事も効率優先な傭兵少女", "ヒューマン", 0, 11, 12, 163, "メルクリウス財団", "田所あずさ", "ミフユ（サマー）", "傭兵などのアルバイト", 108001, 49);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 18, 22, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", "魔族", 0, 12, 7, 157, "悪魔偽王国軍（ディアボロス）", "大坪由佳", "シノブ（ハロウィン）", "占い", 108101, 42);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 14, 23, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "プリン大好きゴースト娘", "魔族", 0, 1, 7, 130, "悪魔偽王国軍（ディアボロス）", "雨宮天", "ミヤコ（ハロウィン）", "プリンを食べること", 108201, 32);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 11, 3, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ちょっとおませな恋に恋する女の子", "魔族", 0, 1, 14, 120, "ルーセント学院", "久野美咲", "ミサキ（ハロウィン）", "ファッション誌鑑賞、コスメ集め", 108301, 22);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 3, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "人々を守るために歌う、唱喚士の少女", "ヒューマン", 0, 6, 4, 163, "カルミナ", "福原綾香", "チカ（クリスマス）", "各種楽器", 108401, 46);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 12, 9, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "泣き虫で臆病な守ってあげたい女の子", "ヒューマン", 0, 6, 9, 150, "サレンディア救護院", "植田佳奈", "クルミ（クリスマス）", "観劇、おままごと", 108501, 40);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 14, 10, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "ぷうきちといつも一緒！", "ヒューマン", 0, 5, 9, 148, "サレンディア救護院", "芹澤優", "アヤネ（クリスマス）", "屋内でできる遊び", 108601, 38);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 16, 27, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", "獣人族", 0, 8, 2, 155, "トゥインクルウィッシュ", "東山奈央", "ヒヨリ（ニューイヤー）", "人助け、応援", 108701, 44);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 5, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", "ヒューマン", 0, 4, 2, 158, "トゥインクルウィッシュ", "種田梨沙", "ユイ（ニューイヤー）", "料理、人間観察", 108801, 47);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 18, 12, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", "魔族", 0, 1, 2, 163, "トゥインクルウィッシュ", "早見沙織", "レイ（ニューイヤー）", "読書、乗馬、お茶", 108901, 46);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 16, 30, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "運命の相手に一途すぎる乙女", "魔族", 0, 7, 13, 154, "トワイライトキャラバン", "橋本ちなみ", "エリコ（バレンタイン）", "実験、裁縫、料理", 109001, 43);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 18, 24, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "お姉ちゃんがお世話してあげるからねっ！", "ヒューマン", 0, 10, 3, 168, "ラビリンス", "生天目仁美", "シズル（バレンタイン）", "家事全般", 109101, 54);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 17, 1, "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", "英霊と契約を結んだマナリアの天才王女", "ヒューマン", 0, 12, "", 156, "？？？", "日笠陽子", "アン", "読書", 109201, 55);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 4, "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", "マナリア魔法学院の新入生", "ヒューマン", 0, 2, "", 144, "？？？", "こやまきみこ", "ルゥ", "食べること、眠ること", 109301, 45);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 17, 3, "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", "人を超越した力を有す心優しい竜姫", "半人半竜", 0, 11, "", 167, "？？？", "福原綾香", "グレア", "ピアノ", 109401, 67);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 18, 19, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "妄想大好き！　ほんとは照れ屋な女の子", "ヒューマン", 0, 11, 15, 157, "ヴァイスフリューゲル　ランドソル支部", "長妻樹里", "クウカ（オーエド）", "小説を読むこと", 109501, 49);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 31, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "トーゴクの神秘、オシエテクダサイ！", "ヒューマン", 0, 8, 15, 163, "ヴァイスフリューゲル　ランドソル支部", "佐藤聡美", "ニノン（オーエド）", "忍法開発", 109601, 51);
