INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 22, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "マホマホ王国のプリンセス", "獣人族", 0, 9, 10, 155, "自警団（カォン）", "内田真礼", "マホ（シンデレラ）", "空想、ぬいぐるみ集め", 116001, 42);
