INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 19, 1, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "弱きを助け強きをくじく猫娘", "獣人族", 0, 3, 12, 158, "メルクリウス財団", "沼倉愛美", "タマキ（作業服）", "猫とたわむれること", 116801, 48);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 20, 11, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "仕事も私事も効率優先な傭兵少女", "ヒューマン", 0, 11, 12, 163, "メルクリウス財団", "田所あずさ", "ミフユ（作業服）", "傭兵などのアルバイト", 116901, 49);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 16, 30, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "運命の相手に一途すぎる乙女", "魔族", 0, 7, 13, 154, "トワイライトキャラバン", "橋本ちなみ", "エリコ（サマー）", "実験、裁縫、料理", 117001, 43);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 18, 24, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "お姉ちゃんがお世話してあげるからねっ！", "ヒューマン", 0, 10, 3, 168, "ラビリンス", "生天目仁美", "シズル（サマー）", "家事全般", 117101, 54);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 17, 24, "", "歌って踊れる大人気アイドル", "ヒューマン", 0, 1, 4, 157, "カルミナ", "日笠陽子", "ノゾミ（サマー）", "舞台鑑賞、ダンス", 117201, 40);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 3, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "人々を守るために歌う、唱喚士の少女", "ヒューマン", 0, 6, 4, 163, "カルミナ", "福原綾香", "チカ（サマー）", "各種楽器", 117301, 46);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 14, 7, "", "ファッション大好きなキュートガール", "ヒューマン", 0, 9, 4, 153, "カルミナ", "木戸衣吹", "ツムギ（サマー）", "裁縫", 117401, 45);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 27, 7, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "実験が趣味の危険な科学者", "ヒューマン", 0, 3, 13, 166, "トワイライトキャラバン", "三石琴乃", "ミツキ（オーエド）", "研究、実験", 117501, 53);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 14, 10, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ボクは誰よりも美しい", "エルフ", 0, 10, 15, 150, "ヴァイスフリューゲル　ランドソル支部", "大空直美", "ユキ（オーエド）", "鏡で自分を見ること", 117601, 40);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 7, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "いつでも「なんくるないさ～」な天然娘", "獣人族", 0, 7, 10, 158, "自警団（カォン）", "高森奈津美", "カオリ（ハロウィン）", "踊り、空手", 117701, 53);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 16, 31, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "トーゴクの神秘、オシエテクダサイ！", "ヒューマン", 0, 8, 15, 163, "ヴァイスフリューゲル　ランドソル支部", "佐藤聡美", "ニノン（ハロウィン）", "忍法開発", 117801, 51);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 10, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "天真爛漫で人気者のカリスマモデル", "魔族", 0, 4, 14, 167, "ルーセント学院", "上坂すみれ", "スズナ（ハロウィン）", "ファッション", 117901, 48);
