INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 23, 14, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "多くの男性を魅了する無垢な女教師", "魔族", 0, 8, 14, 162, "ルーセント学院", "伊藤静", "イオ（ノワール）", "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 119001, 52);
