INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 13, 29, "", "口が達者なヘタレドラゴン", "ドラゴン族", 0, 9, 17, 145, "ドラゴンズネスト", "藤田茜", "イノリ（怪盗）", "ゲーム", 121601, "???");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 17, 5, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "前世を信じる中二病患者、「疾風の冥姫」", "魔族", 0, 7, 13, 159, "トワイライトキャラバン", "髙野麻美", "アンナ（パイレーツ）", "小説執筆", 121901, 45);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 18, 22, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "占いが得意な霊能少女", "魔族", 0, 12, 7, 157, "悪魔偽王国軍（ディアボロス）", "大坪由佳", "シノブ（パイレーツ）", "占い", 122001, 42);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", 13, 6, "", "「友達」に憧れる、エルフの森の女の子", "エルフ", 0, 6, 6, 158, "フォレスティエ", "花澤香菜", "アオイ（キャンプ）", "友達作りのイメトレ", 122101, 44);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 22, 16, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "純情でほっとけない大人の女性", "エルフ", 0, 3, 12, 164, "メルクリウス財団", "今井麻美", "ユカリ（キャンプ）", "ウインドーショッピング", 122201, 55);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("AB", "??", 6, "", "けんぞくのご主人様", "魔族", 0, 12, "", 149, "？？？", "釘宮理恵", "ヴァンピィ", "お散歩、お料理", 122301, 41);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 16, 27, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "人助けが大好き！　前向き格闘娘", "獣人族", 0, 8, 2, 155, "トゥインクルウィッシュ", "東山奈央", "ヒヨリ（サマー）", "人助け、応援", 122401, 44);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("B", 18, 12, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "クールで何事にも真っ直ぐな剣士", "魔族", 0, 1, 2, 163, "トゥインクルウィッシュ", "早見沙織", "レイ（サマー）", "読書、乗馬、お茶", 122501, 46);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 17, 5, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "戦闘のサポートが得意な、心優しい少女", "ヒューマン", 0, 4, 2, 158, "トゥインクルウィッシュ", "種田梨沙", "ユイ（サマー）", "料理、人間観察", 122601, 47);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 8, 2, "", "礼儀正しくしっかり者のちびっ子優等生", "エルフ", 0, 2, 5, 118, "リトルリリカル", "小倉唯", "キョウカ（サマー）", "お勉強", 122701, 21);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 9, 10, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "探検好きのイタズラっ子", "ヒューマン", 0, 8, 5, 128, "リトルリリカル", "諸星すみれ", "ミソギ（サマー）", "いたずら、探検", 122801, 27);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("O", 10, 3, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "お歌もにんじんも、ウサギさんも大好き♪", "獣人族", 0, 4, 5, 117, "リトルリリカル", "日高里菜", "ミミ（サマー）", "かわいいもの集め", 122901, 21);
