INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("A", 14, 2, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "行き倒れの謎のネコミミ魔法使い", "獣人族", 0, 9, 1, 152, "美食殿", "立花理香", "キャル（編入生）", "猫と遊ぶ", 127201, 39);
